<?php $errors=[];$success='';if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$message=trim($_POST['message']??'');if($name===''||!preg_match('/^[a-zA-Z ]{2,}$/',$name))$errors[]='Enter a valid name.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if($message==='')$errors[]='Message is required.';if(!$errors){$file='submissions.csv';$fp=fopen($file,'a');if($fp){if(flock($fp,LOCK_EX)){if(filesize($file)===0)fputcsv($fp,['name','email','message','submitted_at']);fputcsv($fp,[$name,$email,$message,date('c')]);flock($fp,LOCK_UN);$success='Submission saved successfully.';}fclose($fp);}if(!$success)$errors[]='Could not save the record.';}}?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Practical 7</title><style>body{font-family:Arial;background:#eef4ff;margin:0}main{max-width:700px;background:white;margin:35px auto;padding:25px;border-radius:12px}input,textarea{display:block;width:95%;padding:10px;margin:8px 0}button{padding:10px;background:#173b7a;color:white;border:0}.error{color:#b91c1c}.success{color:#166534}</style></head><body><main><h1>Contact Form</h1><?php foreach($errors as $e)echo '<p class="error">'.htmlspecialchars($e,ENT_QUOTES,'UTF-8').'</p>';if($success)echo '<p class="success">'.htmlspecialchars($success,ENT_QUOTES,'UTF-8').'</p>';?><form method="post"><label>Name<input name="name" required value="<?=htmlspecialchars($_POST['name']??'',ENT_QUOTES,'UTF-8')?>"></label><label>Email<input name="email" type="email" required value="<?=htmlspecialchars($_POST['email']??'',ENT_QUOTES,'UTF-8')?>"></label><label>Message<textarea name="message" required><?=htmlspecialchars($_POST['message']??'',ENT_QUOTES,'UTF-8')?></textarea></label><button type="submit">Submit</button></form></main></body></html>